<template>
  <div class="hours-overlay" @click.self="emit('close')"><section class="hours-panel">
    <header class="hours-head"><div class="hours-title"><div class="hours-symbol"><svg viewBox="0 0 24 24"><path d="M3 10h18M5 10V6l7-4 7 4v4M5 10v11h14V10M9 21v-8h6v8"/></svg></div><div><small>CONFIGURACIÓN DEL GIMNASIO</small><h2>HORARIO <span>DEL GIMNASIO</span></h2><p>Establece los días y horarios de apertura de la sede.</p></div></div><button class="hours-close" type="button" aria-label="Cerrar" @click="emit('close')">×</button></header>
    <div class="hours-body"><div class="hours-info"><div><small>SEDE SELECCIONADA</small><strong>Sede {{ sede }}</strong></div><span>{{ abiertos }} días abiertos</span></div>
      <p v-if="error" class="hours-error" role="alert">{{ error }}</p><p v-if="exito" class="hours-success" role="status">{{ exito }}</p>
      <div class="hours-list"><article v-for="(dia,i) in horarios" :key="dia.dia" class="hours-day" :class="{closed:!dia.abierto}"><div class="day-name"><label class="day-switch"><input type="checkbox" v-model="dia.abierto" :disabled="guardando||cargando"><span class="switch-track"></span></label><div><strong>{{ dias[i] }}</strong><small>{{ dia.abierto?'Abierto al público':'Cerrado' }}</small></div></div><div class="day-times"><label>Abre <input type="time" v-model="dia.apertura" :disabled="!dia.abierto||guardando||cargando"/></label><span>—</span><label>Cierra <input type="time" v-model="dia.cierre" :disabled="!dia.abierto||guardando||cargando"/></label></div></article></div>
      <div class="hours-note"><svg viewBox="0 0 24 24"><circle cx="12" cy="12" r="9"/><path d="M12 11v6M12 7h.01"/></svg><span>Este horario define cuándo abre el gimnasio. Las clases y eventos se administran por separado en «Ver horario».</span></div>
    </div><footer class="hours-footer"><button type="button" class="secondary" @click="emit('close')">Cancelar</button><button type="button" class="primary" :disabled="guardando||cargando" @click="guardar">{{ guardando?'Guardando...':'Guardar horario' }}</button></footer>
  </section></div>
</template>
<script setup lang="ts">
import { ref,onMounted,onUnmounted,watch } from 'vue';
const emit=defineEmits(['close','saved']);
type Dia={dia:string;abierto:boolean;apertura:string;cierre:string};
const ids=['monday','tuesday','wednesday','thursday','friday','saturday','sunday'];
const dias=['Lunes','Martes','Miércoles','Jueves','Viernes','Sábado','Domingo'];
const nuevos=():Dia[]=>ids.map(dia=>({dia,abierto:false,apertura:'06:00',cierre:'22:00'}));
const horarios=ref<Dia[]>(nuevos());const sede=ref(1);const abiertos=ref(0);const cargando=ref(false);const guardando=ref(false);const error=ref('');const exito=ref('');
watch(horarios,()=>{abiertos.value=horarios.value.filter(x=>x.abierto).length;},{deep:true,immediate:true});
const base=String(import.meta.env.VITE_API_URL||'').replace(/\/+$/,'').replace(/\/api$/i,'');
const getSede=()=>{for(const st of [sessionStorage,localStorage])for(const key of ['selected_sede_id','sede_id','ID_Sede','id_sede','selectedSede','selectedSedeId','sedeSeleccionada','gym_sede_id']){const raw=st.getItem(key);if(!raw)continue;try{const v=JSON.parse(raw);const n=Number(v&&typeof v==='object'?(v.ID_Sede??v.sede_id??v.id??v.value):v);if(Number.isInteger(n)&&n>0)return n;}catch{const n=Number(raw);if(Number.isInteger(n)&&n>0)return n;}}return 1;};
const getToken=()=>{for(const st of [sessionStorage,localStorage]){for(const k of ['auth_token','token','access_token','gym_token','GYM_ACCOUNT_token','gymAccountToken']){const v=st.getItem(k);if(v)return v.replace(/^Bearer\s+/i,'');}for(const k of ['auth','user','session','gymAccount','gym_account'])try{const v=JSON.parse(st.getItem(k)||'null');const token=v?.token||v?.access_token||v?.accessToken;if(token)return String(token).replace(/^Bearer\s+/i,'');}catch{}}return '';};
const request=async(method:'GET'|'PUT',body?:object)=>{const token=getToken();if(!token)throw new Error('Inicia sesión nuevamente.');let r:Response;try{r=await fetch(`${base}/api/gym/horario-funcionamiento?sede_id=${sede.value}`,{method,headers:{Accept:'application/json',Authorization:`Bearer ${token}`,...(body?{'Content-Type':'application/json'}:{})},...(body?{body:JSON.stringify({...body,sede_id:sede.value})}:{})});}catch{throw new Error('No se pudo conectar con Railway.');}const d=await r.json().catch(()=>null);if(!r.ok){const validation=d?.errors?Object.values(d.errors).flat().join(' '):'';throw new Error(validation||d?.message||`Error HTTP ${r.status}`);}return d;};
let solicitud=0;
const cargar=async()=>{const id=++solicitud;sede.value=getSede();cargando.value=true;error.value='';exito.value='';try{const d=await request('GET');if(id!==solicitud)return;const recibidos=Array.isArray(d.horarios)?d.horarios:[];horarios.value=nuevos().map(x=>{const found=recibidos.find((o:Dia)=>o.dia===x.dia);return found?{dia:x.dia,abierto:!!found.abierto,apertura:String(found.apertura||x.apertura).slice(0,5),cierre:String(found.cierre||x.cierre).slice(0,5)}:x;});}catch(e:any){if(id===solicitud)error.value=e?.message||'Error al consultar los horarios.';}finally{if(id===solicitud)cargando.value=false;}};
const guardar=async()=>{if(guardando.value||cargando.value)return;error.value='';exito.value='';for(const h of horarios.value){if(h.abierto&&(!/^([01]\d|2[0-3]):[0-5]\d$/.test(h.apertura)||!/^([01]\d|2[0-3]):[0-5]\d$/.test(h.cierre)||h.apertura>=h.cierre)){error.value=`Revisa las horas de ${dias[ids.indexOf(h.dia)]}. El cierre debe ser posterior a la apertura.`;return;}}guardando.value=true;try{await request('PUT',{horarios:horarios.value});exito.value='El horario del gimnasio se guardó correctamente.';emit('saved',horarios.value); }catch(e:any){error.value=e?.message||'No se pudo guardar.';}finally{guardando.value=false;}};
const cambioSede=()=>{void cargar();};
onMounted(()=>{window.addEventListener('factorfit:branch-changed',cambioSede);void cargar();});onUnmounted(()=>{window.removeEventListener('factorfit:branch-changed',cambioSede);solicitud++;});
</script>
<style scoped>
*{box-sizing:border-box}.hours-overlay{position:fixed;inset:0;z-index:160;background:rgba(0,0,0,.68);backdrop-filter:blur(5px);display:flex;align-items:center;justify-content:center;padding:16px;font-family:Inter,system-ui,sans-serif;color:var(--color-texto-general,#f5f5f4)}.hours-panel{width:min(810px,96vw);max-height:94vh;overflow:auto;background:var(--bg-cards,#1b1b2b);border:1px solid rgba(255,255,255,.13);border-radius:20px;box-shadow:0 32px 90px #0009}.hours-head{position:sticky;top:0;background:var(--bg-cards,#1b1b2b);z-index:2;display:flex;justify-content:space-between;gap:15px;align-items:center;padding:22px 26px;border-bottom:1px solid #ffffff15}.hours-title{display:flex;align-items:center;gap:14px}.hours-symbol{width:48px;height:48px;flex:none;display:grid;place-items:center;background:#ffad7c15;color:var(--color-highlight,#ffa971);border:1px solid #ffa97155;border-radius:13px}.hours-symbol svg,.hours-note svg{width:22px;height:22px;fill:none;stroke:currentColor;stroke-width:1.8;stroke-linecap:round;stroke-linejoin:round}.hours-head small,.hours-info small{display:block;font-size:10px;font-weight:800;letter-spacing:1.3px;color:#a5a1b6}.hours-head h2{margin:3px 0;font-family:Oswald,Impact,sans-serif;font-size:24px;color:#fff}.hours-head h2 span{color:var(--color-highlight,#ffa971)}.hours-head p{margin:0;font-size:12px;color:#a5a1b6}.hours-close{width:38px;height:38px;border:1px solid #ffffff20;background:#ffffff08;border-radius:10px;color:#bbb;font-size:24px;cursor:pointer}.hours-body{padding:22px 26px}.hours-info{padding:16px 18px;border:1px solid #ffffff1a;border-radius:13px;background:#ffffff07;display:flex;justify-content:space-between;align-items:center;gap:14px;margin-bottom:16px}.hours-info strong{display:block;margin-top:5px;font-size:15px}.hours-info>span{color:#33d399;font-size:12px;font-weight:700}.hours-list{display:grid;gap:9px}.hours-day{display:flex;align-items:center;justify-content:space-between;gap:16px;border:1px solid #ffffff19;background:#ffffff06;border-radius:13px;padding:13px 16px}.hours-day.closed{opacity:.65}.day-name{display:flex;gap:13px;align-items:center}.day-name strong{font-size:14px}.day-name small{display:block;margin-top:4px;color:#a5a1b6;font-size:11px}.day-switch input{position:absolute;opacity:0;width:1px;height:1px}.switch-track{display:block;width:42px;height:24px;border-radius:20px;background:#343347;border:1px solid #ffffff20;position:relative;cursor:pointer}.switch-track:before{content:'';position:absolute;width:17px;height:17px;background:white;border-radius:50%;left:3px;top:2.5px;transition:.15s}.day-switch input:checked+.switch-track{background:var(--color-botones,#e34d78)}.day-switch input:checked+.switch-track:before{transform:translateX(18px)}.day-times{display:flex;align-items:center;gap:8px}.day-times label{font-size:11px;color:#b2aec0}.day-times input{display:block;margin-top:5px;padding:8px 10px;background:#11111d;border:1px solid #ffffff27;border-radius:9px;color:#fff;font-size:13px;color-scheme:dark}.day-times>span{margin-top:15px;color:#999}.hours-note{display:flex;gap:10px;align-items:flex-start;margin-top:18px;padding:14px;border:1px solid #ffa97133;background:#ffa9710d;border-radius:12px;color:#c7c2d0;font-size:12px;line-height:1.5}.hours-note svg{width:18px;height:18px;flex:none;color:#ffa971}.hours-footer{display:flex;justify-content:flex-end;gap:10px;padding:18px 26px 24px;border-top:1px solid #ffffff15}.hours-footer button{padding:13px 19px;border-radius:10px;font-weight:700;cursor:pointer}.hours-footer .secondary{background:transparent;border:1px solid #ffffff25;color:#eee}.hours-footer .primary{background:var(--color-botones,#e34d78);color:var(--color-texto-botones,#fff);border:0}.hours-footer button:disabled{opacity:.6;cursor:wait}.hours-error,.hours-success{border-radius:10px;padding:10px 12px;font-size:12px}.hours-error{background:#ef44441a;color:#ff8585}.hours-success{background:#10b9811a;color:#44e2ad}@media(max-width:660px){.hours-head,.hours-body,.hours-footer{padding:16px}.hours-day{align-items:flex-start;flex-direction:column}.day-times{width:100%}.day-times label{flex:1;min-width:0}.day-times input{width:100%;font-size:16px}.hours-head h2{font-size:20px}}
</style>
